const btn = document.querySelector('#my-btn');

// addEventListener(eventType, handler)
btn.addEventListener('click', function(event) {
  console.log('Clicked!', event);
});

// Arrow function handler (preferred)
btn.addEventListener('click', (event) => {
  console.log('Clicked!', event.target); // the element that was clicked
});

// Named function — required to later remove the listener
function handleClick(event) {
  console.log('Clicked:', event.target.textContent);
}
btn.addEventListener('click', handleClick);
btn.removeEventListener('click', handleClick); // must be same reference

// Mouse events
btn.addEventListener('click', e => {});
btn.addEventListener('dblclick', e => {});
btn.addEventListener('mouseenter', e => {});  // hover in
btn.addEventListener('mouseleave', e => {});  // hover out

// Keyboard events
document.addEventListener('keydown', e => {
  console.log(e.key);    // 'Enter', 'a', 'ArrowUp', etc.
  console.log(e.code);   // 'KeyA', 'Space', 'Enter'
  if (e.key === 'Escape') closeModal();
});

// Form events
const form = document.querySelector('form');
form.addEventListener('submit', e => {
  e.preventDefault();  // stop page reload
  const data = new FormData(form);
  console.log(data.get('email'));
});

const input = document.querySelector('input');
input.addEventListener('input', e => {
  console.log('Current value:', e.target.value);  // fires on every keystroke
});
input.addEventListener('change', e => {});  // fires when focus leaves and value changed
input.addEventListener('focus', e => {});   // element receives focus
input.addEventListener('blur', e => {});    // element loses focus

document.querySelector('#list').addEventListener('click', (event) => {
  // event.target — the element that was actually clicked
  // event.currentTarget — the element the listener is attached to
  const clicked = event.target;

  console.log(clicked.tagName);        // 'LI'
  console.log(clicked.textContent);    // text inside the element
  console.log(clicked.dataset.id);     // data-id attribute
  console.log(event.clientX, event.clientY);  // mouse coordinates
  console.log(event.shiftKey);         // was Shift held?

  // Prevent default browser behavior (link navigation, form submit)
  event.preventDefault();

  // Stop event from bubbling to parent elements
  event.stopPropagation();
});

